import React, { useEffect } from 'react';
import { Dialog, DialogContent, DialogTitle, Slide, Stack } from '@mui/material';
import { Search, SearchIconWrapper, StyledInputBase } from '../../components/Search';
import { MagnifyingGlass } from 'phosphor-react';
import { CallElement } from '../../components/CallElement';
import { MEMBERS_LIST } from '../../data';
import { useDispatch, useSelector } from 'react-redux';
import { FetchFriends } from '../../redux/slices/app';
import { useTheme } from '@mui/material/styles';


const Transition = React.forwardRef(function Transition(props, ref) {
    return <Slide direction="up" ref={ref} {...props} />;
});

const StartCall = ({ open, handleClose }) => {
    const dispatch = useDispatch();
    const theme = useTheme();

    const { friends } = useSelector((state) => state.app);

    useEffect(() => {
        dispatch(FetchFriends());
    }, []);

    return (
        <>

            <Dialog
                fullWidth
                maxWidth='xs'
                open={open}
                TransitionComponent={Transition}
                keepMounted sx={{ p: 4 }}
                onClose={handleClose}
            >
                <Stack spacing={2} sx={{ backgroundColor: theme.palette.mode === 'light' ? "#f5f5f5" : theme.palette.background, }}>
                    <DialogTitle>Start Call</DialogTitle>
                    <DialogContent>
                        <Stack spacing={1.5}>
                            <Stack sx={{ width: "100%" }}>
                                <Search>
                                    <SearchIconWrapper>
                                        <MagnifyingGlass color='#709CE6' />
                                    </SearchIconWrapper>
                                    <StyledInputBase placeholder="Search" />
                                </Search>
                            </Stack>
                            {friends.map((el) => <CallElement {...el} />)}
                        </Stack>
                    </DialogContent>
                </Stack>
            </Dialog>
        </>
    )
}

export default StartCall;