import { Box, IconButton, Stack, Typography } from "@mui/material";
import { MagnifyingGlass, Phone, PhoneCall } from "phosphor-react";
import React, { useEffect, useMemo, useState } from "react";
import { Search, SearchIconWrapper, StyledInputBase } from "../../components/Search";
import { alpha, useTheme } from "@mui/material/styles";
import { CallLogElement } from "../../components/CallElement";
import StartCall from "../../sections/main/StartCall";
import { useDispatch, useSelector } from "react-redux";
import { FetchCallLogs } from "../../redux/slices/app";
import useResponsive from "../../hooks/useResponsive";
import BottomNav from "../../layouts/dashboard/BottomNav";

const Call = () => {
  const dispatch = useDispatch();
  const theme = useTheme();
  const isDesktop = useResponsive("up", "md");
  const { call_logs = [] } = useSelector((state) => state.app);
  const [openDialog, setOpenDialog] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");

  useEffect(() => { dispatch(FetchCallLogs()); }, [dispatch]);

  const filtered = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();
    return call_logs.filter((log) => !query || (log?.name || "").toLowerCase().includes(query) || (log?.type || "").toLowerCase().includes(query));
  }, [call_logs, searchQuery]);

  return (
    <>
      <Stack direction="row" sx={{ width: "100%", minWidth: 0, height: "100vh" }}>
        <Box sx={{ position: "relative", zIndex: 3, width: isDesktop ? 368 : "100vw", height: "100vh", flexShrink: 0, bgcolor: alpha(theme.palette.background.paper, 0.84), backdropFilter: "blur(22px)", borderRight: isDesktop ? `1px solid ${alpha(theme.palette.text.primary, 0.08)}` : 0 }}>
          {!isDesktop && <BottomNav />}
          <Stack height="100%" sx={{ pb: isDesktop ? 0 : 11 }}>
            <Stack px={3} pt={3} pb={2.25} spacing={2.25}>
              <Stack direction="row" alignItems="center" justifyContent="space-between">
                <Stack><Typography variant="h4" sx={{ fontSize: 26 }}>Calls</Typography><Typography variant="caption" color="text.secondary">Recent voice and video calls</Typography></Stack>
                <IconButton aria-label="Start a call" onClick={() => setOpenDialog(true)} sx={{ width: 44, height: 44, color: "white", background: "linear-gradient(135deg, #5C86FF, #4F70E8)", boxShadow: "0 9px 22px rgba(79,124,255,.28)" }}><Phone size={20} weight="fill" /></IconButton>
              </Stack>
              <Search sx={{ height: 48, borderRadius: "15px", bgcolor: alpha(theme.palette.text.primary, 0.045), border: `1px solid ${alpha(theme.palette.text.primary, 0.07)}` }}>
                <SearchIconWrapper><MagnifyingGlass size={19} color={theme.palette.text.secondary} /></SearchIconWrapper>
                <StyledInputBase placeholder="Search calls" inputProps={{ "aria-label": "Search calls" }} value={searchQuery} onChange={(event) => setSearchQuery(event.target.value)} />
              </Search>
            </Stack>
            <Stack px={2} spacing={1} sx={{ flex: 1, minHeight: 0, overflowY: "auto" }}>
              {filtered.length ? filtered.map((item, index) => <CallLogElement key={item.id || index} {...item} />) : (
                <Stack alignItems="center" justifyContent="center" spacing={1.25} sx={{ flex: 1, textAlign: "center", px: 4 }}>
                  <Box sx={{ width: 58, height: 58, borderRadius: "19px", display: "grid", placeItems: "center", color: "primary.main", bgcolor: alpha(theme.palette.primary.main, 0.1) }}><PhoneCall size={26} /></Box>
                  <Typography variant="subtitle2">No calls yet</Typography>
                  <Typography variant="caption" color="text.secondary">Your call history will appear here.</Typography>
                </Stack>
              )}
            </Stack>
          </Stack>
        </Box>
        {isDesktop && (
          <Stack alignItems="center" justifyContent="center" spacing={1.5} sx={{ flex: 1, height: "100%", color: "text.secondary" }}>
            <Box sx={{ width: 86, height: 86, borderRadius: "29px", display: "grid", placeItems: "center", color: "primary.main", bgcolor: alpha(theme.palette.primary.main, 0.09), border: `1px solid ${alpha(theme.palette.primary.main, 0.12)}` }}><PhoneCall size={37} weight="duotone" /></Box>
            <Typography variant="h5" color="text.primary">Call someone you care about</Typography>
            <Typography variant="body2">Start a clear, secure voice or video call.</Typography>
          </Stack>
        )}
      </Stack>
      {openDialog && <StartCall open handleClose={() => setOpenDialog(false)} />}
    </>
  );
};

export default Call;
